  ((select id from public.tax_jurisdictions where state = 'MD' and county = 'Frederick' and city = ''), 'recording', 'Lien certificate / tax status (County Treasurer)', 'Deed', 'both', 'flat', null, 'flat', 25, null, null, null, null, 0, null, 'whole', 'buyer', false, '', '', '', 236, 'Melissa Gamble, CLA, 2026-10-26: Frederick $25.00 (CLA orders by email, not online; paid at recording). Was $20.50 ($20 + assumed 2.5% card fee). County fee, not a Clerk fee; LodeStar bundles it into Section E.'),
