-- FF-091c (Francis Santos, Nov 17 2026, 3:55 PM ET, message 1a1eb4b8017fcabf).
-- Tax rate sheets: one place for each state, county, and city, with its rates, exemptions,
-- questions, and the default buyer / seller split. A blank rate stays blank (the screen says Rate Not Set).
-- Staff can read. Only an Admin or Super admin can change a row. Row security enforces that.
-- NOT APPLIED by this change. Apply by hand on TEST when ready. Never on production.
-- Rollback: supabase/rollbacks/20261125170000_tax_rate_sheets.sql
begin;
set local lock_timeout = '3s';
do $drift$
begin
  if to_regclass('public.tax_jurisdictions') is not null then raise exception 'drift: tax_jurisdictions already exists'; end if;
  if to_regprocedure('private.is_staffish()') is null then raise exception 'drift: private.is_staffish() is missing'; end if;
  if to_regprocedure('private.is_admin()') is null then raise exception 'drift: private.is_admin() is missing'; end if;
end $drift$;

create table public.tax_jurisdictions (
  id uuid primary key default gen_random_uuid(),
  state text not null,
  county text not null default '',
  city text not null default '',
  name text not null,
  active boolean not null default true,
  notes text not null default '',
  updated_at timestamptz,
  constraint tax_jurisdictions_state_chk check (state ~ '^[A-Z]{2}$'),
  constraint tax_jurisdictions_place_uniq unique (state, county, city)
);
comment on table public.tax_jurisdictions is 'FF-091c: a state, a county, or a city that has its own tax rate sheet. Empty county and city means the whole state.';

create table public.tax_rate_lines (
  id uuid primary key default gen_random_uuid(),
  jurisdiction_id uuid not null references public.tax_jurisdictions (id) on delete cascade,
  kind text not null,
  name text not null,
  document text not null default '',
  transaction text not null default 'both',
  basis text not null default 'sale',
  rate numeric(14,6),
  rate_unit text not null default 'percent',
  flat_fee numeric(14,2),
  pages_included integer,
  per_additional_page numeric(14,2),
  page_tier_from integer,
  page_tier_to integer,
  bracket_from numeric(14,2) not null default 0,
  bracket_to numeric(14,2),
  bracket_method text not null default 'whole',
  paid_by text not null default 'buyer',
  round_third boolean not null default false,
  when_key text not null default '',
  when_value text not null default '',
  replaces_name text not null default '',
  sort_order integer not null default 0,
  active boolean not null default true,
  notes text not null default '',
  updated_at timestamptz,
  constraint tax_rate_lines_kind_chk check (kind in ('tax', 'recording')),
  constraint tax_rate_lines_paid_chk check (paid_by in ('buyer', 'seller', 'split')),
  constraint tax_rate_lines_method_chk check (bracket_method in ('whole', 'marginal')),
  constraint tax_rate_lines_tx_chk check (transaction in ('purchase', 'refi', 'both', 'financed')),
  constraint tax_rate_lines_basis_chk check (basis in ('sale', 'loan', 'new_money', 'flat')),
  constraint tax_rate_lines_rate_chk check (rate is null or rate >= 0),
  constraint tax_rate_lines_flat_chk check (flat_fee is null or flat_fee >= 0)
);
comment on column public.tax_rate_lines.rate is 'Blank means Rate Not Set. Do not guess a number.';
comment on column public.tax_rate_lines.flat_fee is 'Blank means Rate Not Set for a recording fee. Zero is a real zero.';
create index tax_rate_lines_place on public.tax_rate_lines (jurisdiction_id);

create table public.tax_exemptions (
  id uuid primary key default gen_random_uuid(),
  jurisdiction_id uuid not null references public.tax_jurisdictions (id) on delete cascade,
  rate_line_id uuid references public.tax_rate_lines (id) on delete cascade,
  code text not null,
  name text not null,
  exempt_amount numeric(14,2),
  alternate_rate numeric(14,6),
  max_price numeric(14,2),
  question_key text not null default '',
  active boolean not null default true,
  notes text not null default '',
  updated_at timestamptz,
  constraint tax_exemptions_amount_chk check (exempt_amount is null or exempt_amount >= 0),
  constraint tax_exemptions_rate_chk check (alternate_rate is null or alternate_rate >= 0)
);
comment on column public.tax_exemptions.exempt_amount is 'Blank means the exemption amount is not set.';
create index tax_exemptions_line on public.tax_exemptions (rate_line_id);

create table public.tax_questions (
  id uuid primary key default gen_random_uuid(),
  jurisdiction_id uuid not null references public.tax_jurisdictions (id) on delete cascade,
  question_key text not null,
  label text not null,
  help text not null default '',
  input_type text not null default 'yes_no',
  choices jsonb not null default '[]'::jsonb,
  scope text not null default 'file',
  transaction text not null default 'both',
  sort_order integer not null default 0,
  active boolean not null default true,
  updated_at timestamptz,
  constraint tax_questions_type_chk check (input_type in ('yes_no', 'money', 'number', 'choice')),
  constraint tax_questions_scope_chk check (scope in ('file', 'deed', 'deed_of_trust', 'both_docs')),
  constraint tax_questions_tx_chk check (transaction in ('purchase', 'refi', 'both')),
  constraint tax_questions_key_uniq unique (jurisdiction_id, question_key)
);

create table public.tax_allocations (
  id uuid primary key default gen_random_uuid(),
  jurisdiction_id uuid not null references public.tax_jurisdictions (id) on delete cascade,
  tax_name text not null,
  document text not null default '',
  transaction text not null default 'purchase',
  default_paid_by text not null,
  law_mandated boolean not null default false,
  when_key text not null default '',
  when_value text not null default 'yes',
  active boolean not null default true,
  notes text not null default '',
  updated_at timestamptz,
  constraint tax_allocations_paid_chk check (default_paid_by in ('buyer', 'seller', 'split')),
  constraint tax_allocations_uniq unique (jurisdiction_id, tax_name, document, transaction, when_key)
);
comment on column public.tax_allocations.law_mandated is 'When true, staff cannot move this line off the default payer. The law fixes the split.';



