alter table public.tax_jurisdictions enable row level security;
alter table public.tax_rate_lines enable row level security;
alter table public.tax_exemptions enable row level security;
alter table public.tax_questions enable row level security;
alter table public.tax_allocations enable row level security;
create policy tax_jurisdictions_staff_read on public.tax_jurisdictions for select to authenticated using ((select private.is_staffish()));
create policy tax_jurisdictions_admin_write on public.tax_jurisdictions for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy tax_rate_lines_staff_read on public.tax_rate_lines for select to authenticated using ((select private.is_staffish()));
create policy tax_rate_lines_admin_write on public.tax_rate_lines for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy tax_exemptions_staff_read on public.tax_exemptions for select to authenticated using ((select private.is_staffish()));
create policy tax_exemptions_admin_write on public.tax_exemptions for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy tax_questions_staff_read on public.tax_questions for select to authenticated using ((select private.is_staffish()));
create policy tax_questions_admin_write on public.tax_questions for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy tax_allocations_staff_read on public.tax_allocations for select to authenticated using ((select private.is_staffish()));
create policy tax_allocations_admin_write on public.tax_allocations for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
revoke all on public.tax_jurisdictions, public.tax_rate_lines, public.tax_exemptions, public.tax_questions, public.tax_allocations from public, anon, authenticated;
grant select, insert, update, delete on public.tax_jurisdictions, public.tax_rate_lines, public.tax_exemptions, public.tax_questions, public.tax_allocations to authenticated;

do $readback$
declare n int; r numeric; locked boolean;
begin
  select count(*) into n from public.tax_jurisdictions where state in ('MD', 'VA', 'DC', 'FL');
  if n < 4 then raise exception 'readback: expected the four states, found %', n; end if;
  select l.rate into r from public.tax_rate_lines l join public.tax_jurisdictions j on j.id = l.jurisdiction_id
    where j.state = 'MD' and j.county = 'Baltimore City' and l.name = 'County transfer tax' and l.bracket_from = 0;
  if r is distinct from 1.5 then raise exception 'readback: Baltimore City transfer rate is %, expected 1.5', r; end if;
  select a.law_mandated into locked from public.tax_allocations a join public.tax_jurisdictions j on j.id = a.jurisdiction_id
    where j.state = 'MD' and j.county = '' and a.tax_name = 'State transfer tax' and a.when_key = 'first_time_buyer';
  if locked is distinct from true then raise exception 'readback: Maryland state transfer tax for a first-time buyer is not locked'; end if;
  if exists (select 1 from public.tax_rate_lines l join public.tax_jurisdictions j on j.id = l.jurisdiction_id where j.county = 'Calvert' and l.name = 'County transfer tax') then
    raise exception 'readback: Calvert county transfer tax was invented'; end if;
  if not (select relrowsecurity from pg_class where oid = 'public.tax_rate_lines'::regclass) then raise exception 'readback: tax rate RLS is off'; end if;
end $readback$;
commit;
